s', 'product-files', 'digital-assets', 'product-images', 'avatars', 'covers', 'store-builder-images', 'onepage-assets', 'lead-form-files-v2', 'lead-form-files', 'product-videos', 'email-images']) as mb where position(quote_literal(mb) in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) > 0) or position('bucket_id' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) = 0)))) as p90_storage_policies, (select count(*) = 3 from information_schema.columns where table_schema = 'public' and table_name = 'email_campaigns' and column_name in ('send_idempotency_key', 'track_opens', 'rendered_html')) as p21_email_sending, (select count(*) = 4 from information_schema.columns where table_schema = 'public' and table_name = 'custom_domains' and column_name in ('purpose', 'is_primary', 'dns_records', 'last_checked_at')) and to_regclass('public.custom_domains_one_primary') is not null as p22_custom_domain_purposes, exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'timezone') and (to_regclass('public.push_tokens') is null or exists (select 1 from pg_constraint where conname = 'push_tokens_platform_check' and pg_get_constraintdef(oid) like '%web%')) as p23_push_time_zone, to_regclass('public.theme_chat_conversations') is not null and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'theme_chat_messages' and column_name = 'conversation_id') and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'theme_chat_conversations' and policyname = 'tcc_own_read') as p24_theme_chat_conversations, to_regprocedure('public.analytics_visit_tally(uuid,uuid,text,bigint,bigint,bigint,bigint,bigint[],bigint[],boolean)') is not null and to_regprocedure('public.analytics_all_time(uuid,uuid)') is not null and to_regclass('public.idx_analytics_events_creator_type_time_id') is not null as p25_analytics_speed, to_regclass('public.business_links